class Solution {
    public int[] elementInNums(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int t = queries[q][0] % (2 * n), idx = queries[q][1];
            if (t <= n) ans[q] = idx < n - t ? nums[t + idx] : -1;
            else ans[q] = idx < t - n ? nums[idx] : -1;
        }
        return ans;
    }
}
